-- F6-A22 P4.5 (#338): identidade funcional da posição.-- Executar somente no ambiente descartável #344.set role service_role;do $$declare  v_a uuid; v_b uuid; v_ver integer; v_msg text; v_rel uuid;begin  -- Mesmo contexto estrutural, duas identidades funcionais distintas.  v_a := public.estrutura_posicao_criar(    'f8a00000-0000-0000-0000-0000000000a1','f8c00000-0000-0000-0000-0000000000a1','f8a20000-0000-0000-0000-0000000000a1',    'f8110000-0000-0000-0000-00000000001b','f8e00000-0000-0000-0000-0000000000a1','f8f00000-0000-0000-0000-0000000000a1','Gerente de Operações Fictício','2026-07-01T00:00:00Z','P4.5 prova A');  v_b := public.estrutura_posicao_criar(    'f8a00000-0000-0000-0000-0000000000a1','f8c00000-0000-0000-0000-0000000000a1','f8a20000-0000-0000-0000-0000000000a2',    'f8110000-0000-0000-0000-00000000001b','f8e00000-0000-0000-0000-0000000000a1','f8f00000-0000-0000-0000-0000000000a1','Gerente de Vendas Fictício','2026-07-01T00:00:00Z','P4.5 prova B');  if v_a = v_b or (select count(*) from public.organizational_positions where id in (v_a,v_b) and name in ('Gerente de Operações Fictício','Gerente de Vendas Fictício')) <> 2 then raise exception '[FAIL] duas posições equivalentes não mantiveram UUID/nome distinto'; end if;  raise notice '[PASS] duas posições com mesma unidade/cargo/senioridade e nomes distintos';  -- Rename mantém a posição que já possui uma relação estrutural.  v_ver := public.estrutura_posicao_renomear('f8a00000-0000-0000-0000-0000000000a1','f8c00000-0000-0000-0000-0000000000a1','f8a20000-0000-0000-0000-0000000000a3','f8310000-0000-0000-0000-000000000003','Posição subordinada renomeada',0,'P4.5 rename');  select id into v_rel from public.position_reporting_lines where subordinate_position_id='f8310000-0000-0000-0000-000000000003';  if v_rel is null or not exists(select 1 from public.organizational_positions where id='f8310000-0000-0000-0000-000000000003' and name='Posição subordinada renomeada') then raise exception '[FAIL] rename não preservou UUID/relação'; end if;  raise notice '[PASS] rename preserva UUID e reporting line';  -- Replay idempotente e replay divergente.  if public.estrutura_posicao_renomear('f8a00000-0000-0000-0000-0000000000a1','f8c00000-0000-0000-0000-0000000000a1','f8a20000-0000-0000-0000-0000000000a3','f8310000-0000-0000-0000-000000000003','Posição subordinada renomeada',0,'P4.5 rename') <> v_ver then raise exception '[FAIL] replay idempotente divergente'; end if;  begin perform public.estrutura_posicao_renomear('f8a00000-0000-0000-0000-0000000000a1','f8c00000-0000-0000-0000-0000000000a1','f8a20000-0000-0000-0000-0000000000a3','f8310000-0000-0000-0000-000000000003','Outro nome',0,'P4.5 rename'); raise exception '[FAIL] replay divergente aceito'; exception when others then if sqlerrm not like 'F5_08_CONFLICT%' then raise; end if; end;  raise notice '[PASS] replay idempotente e divergente';  begin perform public.estrutura_posicao_renomear('f8a00000-0000-0000-0000-0000000000a1','f8c00000-0000-0000-0000-0000000000a1','f8a20000-0000-0000-0000-0000000000a4',v_a,'Nome stale',1,'P4.5 stale'); raise exception '[FAIL] stale version aceito'; exception when others then if sqlerrm not like 'F5_08_CONFLICT%' then raise; end if; end;  begin perform public.estrutura_posicao_renomear('f8a00000-0000-0000-0000-0000000000a1','f8c00000-0000-0000-0000-0000000000a1','f8a20000-0000-0000-0000-0000000000a5',v_a,'   ',0,'P4.5 whitespace'); raise exception '[FAIL] whitespace aceito'; exception when others then if sqlerrm not like 'F5_08_INVALID_INPUT%' then raise; end if; end;  begin perform public.estrutura_posicao_renomear('f8a00000-0000-0000-0000-0000000000b1','f8c00000-0000-0000-0000-0000000000b1','f8a20000-0000-0000-0000-0000000000a6',v_a,'Nome cross','0'::integer,'P4.5 cross'); raise exception '[FAIL] cross-tenant aceito'; exception when others then if sqlerrm not like 'F5_08_%' then raise; end if; end;  begin perform public.estrutura_posicao_renomear('f8a00000-0000-0000-0000-0000000000a1','f8c00000-0000-0000-0000-0000000000a2','f8a20000-0000-0000-0000-0000000000a7',v_a,'Sem capability',0,'P4.5 forbidden'); raise exception '[FAIL] ator sem capability aceito'; exception when others then if sqlerrm not like 'F5_08_FORBIDDEN%' then raise; end if; end;  begin perform public.estrutura_posicao_criar('f8a00000-0000-0000-0000-0000000000a1','f8c00000-0000-0000-0000-0000000000a1','f8a20000-0000-0000-0000-0000000000a8','f8110000-0000-0000-0000-00000000001b','f8e00000-0000-0000-0000-0000000000a1',null,'2026-08-01T00:00:00Z','P4.5 antigo'); raise exception '[FAIL] assinatura antiga executável'; exception when undefined_function then null; end;  raise notice '[PASS] stale/cross-tenant/sem capability/whitespace/assinatura antiga fail-closed';end $$;do $$begin  if not exists (select 1 from information_schema.columns where table_schema='public' and table_name='organizational_positions' and column_name='name' and is_nullable='NO') then raise exception '[FAIL] name não é NOT NULL'; end if;  if to_regprocedure('public.estrutura_posicao_criar(uuid, uuid, uuid, uuid, uuid, uuid, timestamp with time zone, text)') is not null then raise exception '[FAIL] assinatura antiga ainda executável'; end if;  raise notice '[PASS] name NOT NULL e assinatura antiga ausente';end $$;reset role;